class Solution {
  public long maximumProfit(int[] prices, int k) {
    final long NEG = Long.MIN_VALUE / 4;
    long[] free = new long[k + 1]; // best profit with j transactions finished and none open
    long[] holdLong = new long[k + 1]; // j-th transaction open: bought, waiting to sell
    long[] holdShort = new long[k + 1]; // j-th transaction open: sold short, waiting to buy back
    Arrays.fill(holdLong, NEG);
    Arrays.fill(holdShort, NEG);
    for (int p : prices) {
      // descending j so free[j - 1] still holds yesterday's value when a transaction opens
      for (int j = k; j >= 1; j--) {
        free[j] = Math.max(free[j], Math.max(holdLong[j] + p, holdShort[j] - p));
        holdLong[j] = Math.max(holdLong[j], free[j - 1] - p);
        holdShort[j] = Math.max(holdShort[j], free[j - 1] + p);
      }
    }
    return free[k];
  }
}
